<?php
use League\CommonMark\GithubFlavoredMarkdownConverter;use OpenBKAdmin\Helper\GuzzleFactory;use OpenBKAdmin\Helper\OpenBekenHelper;use OpenBKAdmin\Helper\OpenBekenOtaScraper;require_once dirname(__DIR__).'/lang/release_translations.php';$client=GuzzleFactory::getClient($Config);$scraper=new OpenBekenOtaScraper($Config->read('auto_update_channel'),$client);$OpenBekenHelper=new OpenBekenHelper(new GithubFlavoredMarkdownConverter(),$client,$scraper,$Config->read('auto_update_channel'));$releaseNotes=$OpenBekenHelper->getReleaseNotes();$changelog=$OpenBekenHelper->getChangelog();$recentReleases=$scraper->getRecentReleases(10);$hostHeader=trim((string)($_SERVER['HTTP_HOST']??$_SERVER['SERVER_NAME']??''));$detectedHost=preg_replace('/:\d+$/','',$hostHeader);$configuredOtaIp=trim((string)$Config->read('ota_server_ip'));if($configuredOtaIp===''||str_starts_with($configuredOtaIp,'172.30.'))$configuredOtaIp=$detectedHost;$configuredOtaPort=trim((string)$Config->read('ota_server_port'))?:(string)($_SERVER['SERVER_PORT']??'9542');?>
<div class='row justify-content-sm-center upload-form-page'><div class='col col-12 col-md-9 col-xl-8'><h2 class='text-sm-center mb-3'><?php echo$title;?></h2><form class='upload-form' method='post' enctype='multipart/form-data' action='<?php echo _BASEURL_;?>upload'><div class="card upload-form-card mb-4"><div class="card-body"><h4 class="mb-3">OTA Server</h4><div class='row g-4 mb-4'><div class="col col-12 col-sm-9"><label for="ota_server_ip" class="form-label"><?php echo __('CONFIG_SERVER_IP','USER_CONFIG');?></label><input type="text" class="form-control" id="ota_server_ip" name='ota_server_ip' required value='<?php echo htmlspecialchars($configuredOtaIp,ENT_QUOTES,'UTF-8');?>'></div><div class="col col-12 col-sm-3"><label for="ota_server_port" class="form-label"><?php echo __('CONFIG_SERVER_PORT','USER_CONFIG');?></label><input type="text" class="form-control" id="ota_server_port" name='ota_server_port' required value='<?php echo htmlspecialchars($configuredOtaPort,ENT_QUOTES,'UTF-8');?>'></div></div><hr><h4><?php echo obkReleaseT('exec');?></h4><div class="col-12 col-md-6 mb-4"><label class="form-label"><?php echo obkReleaseT('mode');?></label><select class="form-select" name="update_mode"><option value="mass"><?php echo obkReleaseT('mass');?></option><option value="individual"><?php echo obkReleaseT('individual');?></option></select><div class="form-text"><?php echo obkReleaseT('checks');?></div></div><hr><h4><?php echo obkReleaseT('title');?></h4><div class="alert alert-info py-2"><?php echo obkReleaseT('notice');?></div><div class="row g-3 align-items-end mb-3"><div class="col"><label class="form-label"><?php echo obkReleaseT('version');?></label><select class="form-select" name="official_release"><?php if(empty($recentReleases)){?><option value="latest"><?php echo obkReleaseT('latest');?></option><?php }else foreach($recentReleases as$i=>$r){$v=(string)$r['version'];?><option value="<?php echo htmlspecialchars($v,ENT_QUOTES,'UTF-8');?>" <?php echo$i===0?'selected':'';?>><?php echo htmlspecialchars($v,ENT_QUOTES,'UTF-8');?></option><?php }?></select><div class="form-text"><?php echo obkReleaseT('help');?></div></div><div class="col col-12 col-md-auto"><button type='submit' class='btn btn-primary w-100' name='auto' value='submit'><?php echo obkReleaseT('use');?></button></div></div><hr><h4><?php echo obkReleaseT('local');?></h4><div class='row g-3 align-items-end'><div class="col"><label for="new_firmware" class="form-label"><?php echo obkReleaseT('file');?></label><input type="file" class="form-control" id="new_firmware" name='new_firmware' accept=".rbl,.bin,.img,.ota"></div><div class="col col-12 col-md-auto"><button type='submit' class='btn btn-secondary w-100' id="localUpload" name='upload' value='submit'><?php echo obkReleaseT('uselocal');?></button></div></div></div></div></form><div class='row g-4'><div class='col col-12 col-md-6'><div class='card h-100'><div class='card-body changelog'><?php echo$releaseNotes;?></div></div></div><div class='col col-12 col-md-6'><div class='card h-100'><div class='card-body changelog'><?php echo$changelog;?></div></div></div></div></div></div><script>document.addEventListener('DOMContentLoaded',()=>{const f=document.querySelector('#new_firmware'),l=document.querySelector('#localUpload');if(l)l.addEventListener('click',e=>{if(!f.files.length){e.preventDefault();f.focus();f.reportValidity();}});});</script>
